<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentUserVO;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\Holder\UserRoleAssignamentUserAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserRoleAssignamentUserAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserRoleAssignamentUserAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getUser returns null on a freshly created holder.
         */
        public function testUserNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithUserRoleAssignamentUserAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isUserAssigned());
            $this->assertNull($holder->getUser());
        }
}
class ImplWithUserRoleAssignamentUserAttributeHolderUnitTest
{
  use UserRoleAssignamentUserAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedUserRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultUser();
    }}
